$\widehat{MQR} = \widehat{EQP} \left( = \widehat{MBR} = \widehat{FQT} \right) \Rightarrow \widehat{MQR} + \widehat{RQP} = \widehat{EQP} + \widehat{RQP} = \widehat{RQE} = 180^{\circ}$\\
$\Rightarrow \widehat{MQP} = 180^{\circ} \Rightarrow {M, Q, P} \text{thẳng hàng}$
}\end{ex}

